select account_type, case when balance >= 85000 then 'high' when balance >= 13000 then 'mid' else 'low' end as balance_bucket, sum(balance) as total_balance, round((100 * sum(case when status = 'CLOSED' then 1 else 0 end)) / count(*), 1) as pct_closed from accounts group by account_type, case when balance >= 85000 then 'high' when balance >= 13000 then 'mid' else 'low' end
